CREATE OR REPLACE FUNCTION public.finalize_sale(
  p_operation_id uuid,
  p_payment_method text,
  p_amount_paid numeric,
  p_items jsonb
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  line_item jsonb;
  product_row public.products%ROWTYPE;
  purchase_total numeric(12,2) := 0;
  final_result jsonb;
  created_sale_id bigint;
  paid_value numeric(12,2);
  change_value numeric(12,2);
  item_quantity numeric(14,3);
BEGIN
  SELECT result INTO final_result FROM public.sync_operations WHERE operation_id = p_operation_id;
  IF FOUND THEN RETURN final_result; END IF;
  IF jsonb_array_length(p_items) = 0 THEN RAISE EXCEPTION 'Inclua ao menos um item na venda.'; END IF;
  IF p_payment_method NOT IN ('dinheiro', 'debito', 'credito', 'pix') THEN RAISE EXCEPTION 'Forma de pagamento inválida.'; END IF;
  FOR line_item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    item_quantity := (line_item->>'quantity')::numeric;
    IF item_quantity <= 0 THEN RAISE EXCEPTION 'Quantidade inválida.'; END IF;
    SELECT * INTO product_row FROM public.products WHERE id = (line_item->>'productId')::bigint AND active = true FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Produto indisponível.'; END IF;
    IF product_row.stock_current < item_quantity THEN RAISE EXCEPTION 'Estoque insuficiente para %.', product_row.name; END IF;
    purchase_total := purchase_total + round(product_row.sale_price * item_quantity, 2);
  END LOOP;
  paid_value := CASE WHEN p_payment_method = 'dinheiro' THEN COALESCE(p_amount_paid, 0) ELSE purchase_total END;
  IF p_payment_method = 'dinheiro' AND paid_value < purchase_total THEN RAISE EXCEPTION 'O valor recebido é menor que o total da compra.'; END IF;
  change_value := CASE WHEN p_payment_method = 'dinheiro' THEN round(paid_value - purchase_total, 2) ELSE 0 END;
  INSERT INTO public.sales (client_sale_id, payment_method, total_amount, amount_paid, change_amount, item_count)
  VALUES (p_operation_id, p_payment_method, purchase_total, paid_value, change_value, jsonb_array_length(p_items))
  RETURNING id INTO created_sale_id;
  FOR line_item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    item_quantity := (line_item->>'quantity')::numeric;
    SELECT * INTO product_row FROM public.products WHERE id = (line_item->>'productId')::bigint FOR UPDATE;
    UPDATE public.products SET stock_current = stock_current - item_quantity, updated_at = now() WHERE id = product_row.id;
    INSERT INTO public.sale_items (sale_id, product_id, product_name, barcode, unit, unit_price, quantity, subtotal)
    VALUES (created_sale_id, product_row.id, product_row.name, product_row.barcode, product_row.unit, product_row.sale_price, item_quantity, round(product_row.sale_price * item_quantity, 2));
  END LOOP;
  final_result := jsonb_build_object('saleId', created_sale_id, 'total', purchase_total, 'amountPaid', paid_value, 'change', change_value);
  INSERT INTO public.sync_operations (operation_id, operation_type, result) VALUES (p_operation_id, 'sale', final_result);
  RETURN final_result;
END;
$function$;
